// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

edits.newText:
// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility lives
// in `brickHit()`, called from the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball was before this move: `frame()` sweeps from there
  // to the new position so a fast ball cannot tunnel through a brick (#1).
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

