export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: the bounce itself lives in the pure `brickHit()` (issue #1); the
  // draw pass only scores what it destroyed. Swept detection uses the
  // previous position recorded by `step()`.
  const destroyed = brickHit(state.ball, state.bricks, state.ball.px, state.ball.py);
  for (const brick of destroyed) {
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

