edits.newText:
// --- Issue #1: the ball must bounce off bricks, not plow through -----------

// A brick with default geometry, alive by default.
function makeBrick(x, y, row = 0) {
  return { x, y, w: BRICK_W, h: BRICK_H, row, alive: true, points: 10 };
}

// A ball placed already overlapping a brick: 3 px of penetration on the face
// under test, 17 px or more on the other axis. Nothing moves, so the bounce
// is judged on geometry alone.
function makeBall(x, y, vx, vy) {
  return { x, y, r: BALL_R, vx, vy };
}

test('brickHit: left face hit flips vx, leaves vy untouched', () => {
  const ball = makeBall(96, 110, 300, 30);
  brickHit(ball, [makeBrick(100, 100)]);
  assert.ok(ball.vx < 0, `vx should flip left: ${ball.vx}`);
  assert.equal(ball.vy, 30);
});

test('brickHit: right face hit flips vx, leaves vy untouched', () => {
  const ball = makeBall(176, 110, -300, 30);
  brickHit(ball, [makeBrick(100, 100)]);
  assert.ok(ball.vx > 0, `vx should flip right: ${ball.vx}`);
  assert.equal(ball.vy, 30);
});

test('brickHit: top face hit flips vy, leaves vx untouched', () => {
  const ball = makeBall(136, 96, 30, 300);
  brickHit(ball, [makeBrick(100, 100)]);
  assert.ok(ball.vy < 0, `vy should flip up: ${ball.vy}`);
  assert.equal(ball.vx, 30);
});

test('brickHit: bottom face hit flips vy, leaves vx untouched', () => {
  const ball = makeBall(136, 124, 30, -300);
  brickHit(ball, [makeBrick(100, 100)]);
  assert.ok(ball.vy > 0, `vy should flip down: ${ball.vy}`);
  assert.equal(ball.vx, 30);
});

test('brickHit: corner hit (equal penetrations) flips both components', () => {
  const ball = makeBall(96, 96, 300, 300);
  brickHit(ball, [makeBrick(100, 100)]);
  assert.ok(ball.vx < 0, `vx should flip left: ${ball.vx}`);
  assert.ok(ball.vy < 0, `vy should flip up: ${ball.vy}`);
});

test('brickHit: pushes the ball back out on every face (no sticky bounce)', () => {
  const left = makeBall(96, 110, 300, 30);
  brickHit(left, [makeBrick(100, 100)]);
  assert.ok(left.x + BALL_R <= 100, `left face: right edge at ${left.x + BALL_R}`);

  const right = makeBall(176, 110, -300, 30);
  brickHit(right, [makeBrick(100, 100)]);
  assert.ok(right.x - BALL_R >= 172, `right face: left edge at ${right.x - BALL_R}`);

  const top = makeBall(136, 96, 30, 300);
  brickHit(top, [makeBrick(100, 100)]);
  assert.ok(top.y + BALL_R <= 100, `top face: bottom edge at ${top.y + BALL_R}`);

  const bottom = makeBall(136, 124, 30, -300);
  brickHit(bottom, [makeBrick(100, 100)]);
  assert.ok(bottom.y - BALL_R >= 120, `bottom face: top edge at ${bottom.y - BALL_R}`);
});

test('brickHit: after the push-out the ball no longer overlaps, so the bounce applies once', () => {
  const ball = makeBall(96, 110, 300, 30);
  const bricks = [makeBrick(100, 100)];
  brickHit(ball, bricks);
  // The brick is dead now; revive it to prove the POSITION alone keeps the
  // ball clear (a sticky-bounce fix would re-flip here).
  bricks[0].alive = true;
  const { vx, vy } = ball;
  brickHit(ball, bricks);
  assert.equal(ball.vx, vx, 'velocity must not be flipped twice');
  assert.equal(ball.vy, vy);
});

test('brickHit: a horizontal seam hits two bricks in one pass and bounces once', () => {
  const ball = makeBall(176, 126, 6, -60);
  const bricks = [makeBrick(100, 100), makeBrick(100 + BRICK_W + BRICK_GAP, 100)];
  brickHit(ball, bricks);
  assert.ok(ball.vy > 0, `vy must flip exactly once: ${ball.vy}`);
  assert.equal(ball.vx, 6);
  assert.ok(!bricks[0].alive && !bricks[1].alive, 'both seam bricks destroyed');
});

test('brickHit: a vertical seam bounces once too', () => {
  const ball = makeBall(94, 124, 60, 6);
  const bricks = [makeBrick(100, 100), makeBrick(100, 100 + BRICK_H + BRICK_GAP)];
  brickHit(ball, bricks);
  assert.ok(ball.vx < 0, `vx must flip exactly once: ${ball.vx}`);
  assert.equal(ball.vy, 6);
  assert.ok(!bricks[0].alive && !bricks[1].alive, 'both seam bricks destroyed');
});

test('brickHit: swept path catches a fast ball (no tunnelling)', () => {
  // Level 6 with dt capped at 50 ms: 35.5 px per step against a 34 px
  // crossing (BRICK_H + ball diameter). Discrete sampling would miss it.
  const ball = makeBall(136, 92.5, 0, -ballSpeed(6));
  const bricks = [makeBrick(100, 100)];
  brickHit(ball, bricks, 136, 128); // previous position: below the brick
  assert.ok(!bricks[0].alive, 'brick must be destroyed');
  assert.ok(ball.vy > 0, `ball must bounce back down: ${ball.vy}`);
});

test('frame(): the full loop catches a tunneling ball through step() then frame()', () => {
  const state = createState(6);
  const brique = { x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 };
  state.bricks = [brique];
  state.ball = { x: 136, y: 128, r: BALL_R, vx: 0, vy: -ballSpeed(6) };

  const ctx = fakeContext();
  frame(ctx, state); // ball is below the brick: nothing happens yet
  step(state, 0.05); // the 35.5 px jump lands above the brick...
  frame(ctx, state); // ...and the swept pass resolves the crossing

  assert.ok(!brique.alive, 'brick must be destroyed');
  assert.ok(state.ball.vy > 0, `ball must bounce back down: ${state.ball.vy}`);
});

// A canvas context that swallows every drawing call.
function fakeContext() {
  const nothing = () => {};
  return new Proxy(
    {},
    {
      get: (_, key) => (key === 'canvas' ? { width: WIDTH, height: HEIGHT } : nothing),
      set: () => true,
    },
  );
}

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

